using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.Evaluation;

/// <summary>
/// Shared fixture that starts the AppHost once for all evaluation scenarios.
/// </summary>
public sealed class EvaluationHarness : IAsyncLifetime
{
    private DistributedApplicationFactory? _factory;

    public DistributedApplicationFactory Factory =>
        _factory ?? throw new InvalidOperationException("Harness not initialized.");

    public async ValueTask InitializeAsync()
    {
        _factory = new DistributedApplicationFactory(typeof(Program));
        await _factory.StartAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_factory is not null)
        {
            await _factory.DisposeAsync();
        }
    }
}

[CollectionDefinition(Name)]
public class EvaluationCollection : ICollectionFixture<EvaluationHarness>
{
    public const string Name = "Evaluation";
}

using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.Evaluation;

[Collection(EvaluationCollection.Name)]
public class AppHostTests
{
    private readonly EvaluationHarness _harness;

    public AppHostTests(EvaluationHarness harness)
    {
        _harness = harness;
    }

    [Fact]
    public async Task AppHost_StartsSuccessfully()
    {
        // The harness ensures the app host starts; verify it is not null and running.
        var app = _harness.Factory;
        Assert.NotNull(app);

        // Verify all resources reach a running/healthy state.
        await app.WaitForResources().WaitAsync(TimeSpan.FromSeconds(60));
    }

    [Fact]
    public async Task AppHost_AllResourcesHealthy()
    {
        var app = _harness.Factory;
        var resources = app.GetResources();

        Assert.NotEmpty(resources);

        foreach (var resource in resources)
        {
            Assert.True(
                resource.State is "Running" or "Finished",
                $"Resource '{resource.Name}' in unexpected state: {resource.State}");
        }

        await Task.CompletedTask;
    }
}

